update public.fields set verification_status='verified_against_standard', verification_quote='Die vorliegenden Regelungen zielen vorrangig auf eine Anwendung bei folgenden Veranlassungen: I städtebauliche und/oder entwässerungstechnische Neuerschließung von Siedlungsflächen; I städtebauliche und/oder entwässerungstechnische Überplanung von Siedlungsgebieten (z. B. Nachverdichtung, Nutzungskonversion, städtebauliche Sanierung); | I Entwicklung geeigneter Maßnahmen im Rahmen von Maßnahmenprogrammen nach EG-WRRL zur Behebung festgestellter Defizite des Gewässerzustands, verursacht durch siedlungsbedingte Veränderungen der lokalen Wasserhaushaltsgrößen und des Abflussregimes. — printed p.10', verification_note='md-verified 2026-09-05 (§1 Anwendungsbereich, printed p.10) [VC]', verified_at=now() where id='421a7064-6dc8-4e1f-b1b8-d1b3d6942a30' and verification_status not in ('verified_against_standard','corrected');
-- relevance_check_required
update public.fields set verification_status='verified_against_standard', verification_quote='In den Arbeitsblättern DWA-A 102-1/BWK-A 3-1 und DWA-A 102-2/BWK-A 3-2 ist die emissionsbezogene Zielvorgabe „Erhalt des lokalen Wasserhaushalts“ verankert. Sie beinhaltet die Planungsaufgabe, die drei Bilanzgrößen des Bilanzgebiets im bebauten Zustand denen des unbebauten Referenzzustands im langjährigen Mittel soweit wie möglich anzunähern (siehe 5.2). Der entsprechende Vergleich der Wasserbilanz im bebauten und unbebauten Zustand sollte für Bilanzgebiete ab einer befestigten Fläche $A_{E, k, b}$ von ca. $800 \mathrm{~m}^{2}$ (Relevanzgrenze analog DIN 1986-100 bzgl. dortigem Überflutungsnachweis zur Grundstücksentwässerung) geführt werden. Geeignete Maßnahmen zur Niederschlagswasserbewirtschaftung (siehe 4.3) sind unabhängig von der Größe des Bilanzgebiets zu wählen und rechtlich langfristig abzusichern. — printed p.23', verification_note='md-verified 2026-09-05 (§5.3.3, printed p.23; the printed threshold is "ca. 800 m²" under "sollte", i.e. a relevance guide, not a hard limit) [VC]', verified_at=now() where id='1b5ffe9b-0edd-49fb-9d60-930b1791fdb5' and verification_status not in ('verified_against_standard','corrected');
-- A_total
update public.fields set verification_status='verified_against_standard', verification_quote='Das Bilanzgebiet umfasst I den Bereich der Neuerschließung von Siedlungsflächen, der in der Regel durch einen bestehenden oder beabsichtigten Bebauungsplan verortet ist; | I den Bereich einer städtebaulichen oder entwässerungstechnischen Überplanung von Siedlungsflächen im Bestand. | Die Wasserbilanz wird erstellt für die kanalisierte Einzugsgebietsfläche AE,k im Bilanzgebiet einschließlich zugehöriger nicht bebaubarer Flächen (z. B. Vegetationsflächen etc.). Die Bilanzgrößen sind die langjährigen Mittelwerte des Direktabflusses, der Grundwasserneubildung und der Verdunstung. — printed p.21', verification_note='md-verified 2026-09-05 (§5.3.1 Bilanzgebiet und -größen, printed p.21; caveat: the guideline sizes the Bilanzgebiet by A_E,k and puts the 800 m² relevance guide on A_E,k,b, not on a Grundstücksfläche) [VC]', verified_at=now() where id='f7c5b422-6d99-4565-ab87-af1300684e36' and verification_status not in ('verified_against_standard','corrected');
