-- ---------- M104-04 Niederschlagsdaten ----------
-- P
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Formelzeichen | In der Siedlungshydrologie wird in den meisten Anwendungsfällen mit nicht korrigierten Niederschlagsdaten gerechnet. Für die Langzeitsimulationen zur Ableitung der Regressionsgleichungen für die Aufteilungswerte lagen nicht korrigierte Niederschlagszeitreihen vor. Eine Korrektur der Monatsund Jahresniederschläge wäre mit dem Ansatz gemäß HAD (BfG 2003a) denkbar gewesen, nicht jedoch eine sachgerechte Korrektur der zeitlich hoch aufgelösten Zeitreihen. Daher wurde aus Gründen der Datenintegrität entschieden, die Langzeitsimulationen mit den unkorrigierten Originaldaten durchzuführen. In den Regressionsgleichungen A. 2 bis A. 10 wird folglich der unkorrigierte mittlere Jahresniederschlag $P$ verwendet. Die resultierenden Aufteilungswerte (Tabelle A.1) gelten im Rahmen des vorliegenden Merkblatts für die Bilanzen mit korrigierten Jahresniederschlägen gemäß 5.3. | | $P$ | mm/a | Mittlere jährliche Niederschlagshöhe (entspricht $h_{\mathrm{Na}, \mathrm{m}}$ ) | — printed p.13, p.26', verification_note='md-verified 2026-09-05 (Tab. 2 Formelzeichen (§3.3), printed p.13–15 + §A.1 printed p.26 (Anhang A/B regressions use the UNCORRECTED P)) [VC]', verified_at=now() where id='76c6ea50-494b-4e9d-b995-be5d6be5dc3b' and verification_status not in ('verified_against_standard','corrected');
