update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Formelzeichen | Die Wasserbilanz wird erstellt für die kanalisierte Einzugsgebietsfläche AE,k im Bilanzgebiet einschließlich zugehöriger nicht bebaubarer Flächen (z. B. Vegetationsflächen etc.). Die Bilanzgrößen sind die langjährigen Mittelwerte des Direktabflusses, der Grundwasserneubildung und der Verdunstung. | | $A_{\mathrm{E}, \mathrm{k}}$ | ha | Durch das Entwässerungssystem erfasste Einzugsgebietsfläche l.,kanalisiertes Einzugsgebiet") | — printed p.13, p.21', verification_note='md-verified 2026-09-05 (Tab. 2 Formelzeichen (§3.3), printed p.13–15 + §5.3.1 printed p.21) [VC]', verified_at=now() where id='9fe68000-27c7-45bd-8c25-ddc2a8a668db' and verification_status not in ('verified_against_standard','corrected');
