-- anteil_befestigt
update public.fields set verification_status='verified_against_standard', verification_quote='Die mit der Bebauung verbundenen Eingriffe in die hydrologischen Prozesse Infiltration und Evapotranspiration verändern den Wasserhaushalt in Siedlungen und das Abflussregime siedlungsnaher Gewässer (u. a. Leopold 1968, White \& Greer 2006, Ya et al. 2012, Barron et al. 2003). Das Ausmaß der Veränderung wird maßgeblich durch den Anteil befestigter Flächen im Siedlungsgebiet geprägt. — printed p.16', verification_note='md-verified 2026-09-05 (§4.1 Fachliche Grundlagen, printed p.16) [VC]', verified_at=now() where id='2cef8a3a-057b-4d17-8cd1-d243f541c8cf' and verification_status not in ('verified_against_standard','corrected');
-- anteil_unbefestigt
update public.fields set verification_status='verified_against_standard', verification_quote='Die mit der Bebauung verbundenen Eingriffe in die hydrologischen Prozesse Infiltration und Evapotranspiration verändern den Wasserhaushalt in Siedlungen und das Abflussregime siedlungsnaher Gewässer (u. a. Leopold 1968, White \& Greer 2006, Ya et al. 2012, Barron et al. 2003). Das Ausmaß der Veränderung wird maßgeblich durch den Anteil befestigter Flächen im Siedlungsgebiet geprägt. | Der Wasserhaushalt undurchlässig befestigter Flächen weist einen sehr hohen Direktabfluss, eine geringe Grundwasserneubildung und eine geringe Verdunstung auf. Der Wasserhaushalt durchlässig befestigter und insbesondere nicht befestigter Flächen ist durch eine höhere Grundwasserneubildung und Verdunstung sowie einen geringeren Direktabfluss gekennzeichnet. Die Größe der drei Komponenten des Wasserhaushalts wird durch die örtlichen Gegebenheiten von Boden, Grundwasserverhältnissen, Vegetationsart und -dichte sowie den meteorologischen Randbedingungen von Niederschlag und potenzieller Verdunstung bestimmt. — printed p.16', verification_note='md-verified 2026-09-05 (§4.1 Fachliche Grundlagen, printed p.16) [VC]', verified_at=now() where id='d4a3b583-e5f8-4eed-8e66-1f5e956d483c' and verification_status not in ('verified_against_standard','corrected');

