-- balance_sum_check
update public.fields set verification_status='verified_against_standard', verification_quote='Für die Aufteilungswerte gilt die Kontrollbedingung $a_{\mathrm{F}}+g_{\mathrm{F}}+v_{\mathrm{F}}=1$. Die Regressionsgleichungen für $a_{\mathrm{F}}$, $g_{F}$, und $v_{F}$ wurden für jede einzelne Größe individuell ermittelt. Dies kann dazu führen, dass ihre Summe im ersten Rechenschritt ungleich 1 ist. In diesem Fall sind die drei Aufteilungswerte mit dem Faktor $1 /\left(a_{\mathrm{F}}+g_{\mathrm{F}}+v_{\mathrm{F}}\right)$ zu multiplizieren. | Für die Aufteilungswerte gilt die Kontrollbedingung $a_{F}+g_{F}+v_{F}=1$. Bilanzfehler lassen sich korrigieren, indem die drei Aufteilungswerte mit dem Faktor $1 /\left(a_{F}+g_{F}+v_{F}\right)$ multipliziert werden. Bevor die Korrekturrechnung erfolgt, ist die Berechnung der Aufteilungswerte nochmals sorgfältig zu prüfen, um Rechenfehler als Ursache für die Differenzen auszuschließen. — printed p.26, p.46', verification_note='md-verified 2026-09-05 (§A.1 Hinweis zur Korrektur von Bilanzfehlern p.26 + §C.6 p.46 (Kontrollbedingung a_F + g_F + v_F = 1, correction factor 1/(a_F+g_F+v_F))) [VC]', verified_at=now() where id='a714fea5-0adb-46e0-83a7-4d308b286cbb' and verification_status not in ('verified_against_standard','corrected');

-- ---------- M104-22 Anlagentyp-Wahl ----------
-- Z
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Formelzeichen | Der Zufluss zu einer Bewirtschaftungsanlage ist der Direktabfluss der angeschlossenen befestigten Fläche. Bei großen, nach oben offenen Anlagen wird deren Überregnung zusätzlich mit in Ansatz gebracht. Der Zufluss wird aufgeteilt in die Komponenten Oberflächenabfluss, Grundwasserneubildung und Verdunstung. Es gilt: | Z=a_{\mathrm{F}} \cdot P_{\text {korr }} & \text { in } \mathrm{mm} / \mathrm{a} \\ Z=a_{\mathrm{A}} \cdot Z+g_{\mathrm{A}} \cdot Z+v_{\mathrm{A}} \cdot Z & \text { in } \mathrm{mm} / \mathrm{a} \tag{12} | | Z | - | Zufluss zur Bewirtschaftungsanlage | — printed p.13, p.22', verification_note='md-verified 2026-09-05 (Tab. 2 Formelzeichen (§3.3), printed p.13–15 + §5.3.2.3 Gln. (11) und (12) printed p.22) [VC]', verified_at=now() where id='4c7e469a-1491-4127-9063-f3c348efacf7' and verification_status not in ('verified_against_standard','corrected');
