-- attest_m104_29_req_19
update public.fields set verification_status='verified_against_standard', verification_quote='Die Bilanzergebnisse können im hydrologischen Dreieck (Bild 2) gemeinsam dargestellt werden. Die Analyse von Praxisbeispielen und Beispielrechnungen zeigt, dass Abweichungen in den Aufteilungswerten $a, g$ und $v$ gegenüber dem unbebauten Referenzzustand von 5 bis 10 Prozentpunkten erreichbar sind, wenn die vielfältigen Möglichkeiten der Niederschlagswasserbewirtschaftung genutzt werden. Die Abweichungen sind unter ökologischen, technischen und wirtschaftlichen Aspekten zu bewerten. Größere Abweichungen, die aus unvermeidbaren Randbedingungen oder Zwängen herrühren, sind ausführlich fachlich zu begründen und ihre Berücksichtigung im Rahmen von Ersatz- und Ausgleichsregelungen zu prüfen. — printed p.23', verification_note='md-verified 2026-09-05 (§5.3.3, printed p.23 (attestation carrier for gate REQ-19)) [VC]', verified_at=now() where id='657a0c8d-8407-4d5d-b21e-746070aa4722' and verification_status not in ('verified_against_standard','corrected');
