-- ---------- M104-30 Flächengewichtete Mittelwertbildung ----------
-- gewichtungsmethode
update public.fields set verification_status='verified_against_standard', verification_quote='Im Interesse eines reibungslosen Planungsablaufs wird empfohlen, die Wasserbilanz für den Referenzzustand vor Beginn städtebaulicher Planungen zu erarbeiten und als Zielvorgabe festzulegen. Im städtebaulichen oder entwässerungstechnischen Entwurf können somit Bewirtschaftungsmaßnahmen frühzeitig entwickelt und mit dem Bilanzverfahren bewertet werden. Flächen gleicher Art können im Bilanzgebiet zusammengefasst bilanziert werden. | 1. Die Berechnung erfolgt für die einzelnen Teilflächen von $A_{\mathrm{E}, \mathrm{K}, \mathrm{nb}}$ und die Ergebnisse werden anschließend für das gesamte Bilanzgebiet summiert. Die Vorgehensweise ist bei digitaler Planbe- arbeitung mit GIS-Anbindung zweckmäßig. 2. Die Berechnung erfolgt für mehrere Gruppen gleichartiger Flächen, deren Resultate für das gesamte Bilanzgebiet summiert werden. Die Vorgehensweise ist für weniger digital ausgerichtete Planungsvorhaben geeignet. — printed p.23, p.38', verification_note='md-verified 2026-09-05 (§5.3.4 printed p.23 + §C.2 printed p.38 (the two printed aggregation routes)) [VC]', verified_at=now() where id='adfa3a73-d86d-4752-bbce-92fbe262948f' and verification_status not in ('verified_against_standard','corrected');
-- a_E_gewichtet
