-- bilanz_check_ref
update public.fields set verification_status='verified_against_standard', verification_quote='Der HAD führt die hydrologischen Grundlagendaten für Raster von $1 \mathrm{~km}^{2}$ zusammen. Dem HAD liegt ein rasterbasiertes Regionalisierungsverfahren zugrunde. Die Wasserhaushaltsgrößen wurden punktuell mit dem Wasserhaushaltsverfahren BAGLUVA (BfG 2003b) berechnet, großräumig regionalisiert und in Rastern von je $1 \mathrm{~km}^{2}$ diskretisiert. Je Rasterfeld werden Wertebereiche für die Wasserhaushaltsgrößen angegeben. Bei kleinräumigen Betrachtungen können Unschärfen der hydrologischen Kenndaten auftreten, die eine fachliche Interpretation der hydrologischen Verhältnisse erfordern. So ergab eine Analyse, dass in etwa $10 \%$ der Rasterfelder des HAD die Summe der Größen $R_{\mathrm{D}}$, GWN und $E T_{\mathrm{a}}$ in der Bilanz gemäß GL. (6) um mehr als $4 \%$ von der Bezugsgröße $P_{\text {korr }}$ abweichen kann. | Die Korrektur von Bilanzfehlern erfolgt am einfachsten, indem die Aufteilungswerte $a, g$ und $v$ gemäß den Gln. (7) bis (9) mit dem Faktor $1 /(a+g+v)$ multipliziert werden. — printed p.21', verification_note='md-verified 2026-09-05 (§5.2.5, printed p.21 (HAD raster balance error up to 4 %; correction factor 1/(a+g+v))) [VC]', verified_at=now() where id='caab51c9-1e04-4e6e-a446-6b3752664f5d' and verification_status not in ('verified_against_standard','corrected');
-- nachweis_a
update public.fields set verification_status='verified_against_standard', verification_quote='Die Bilanzergebnisse können im hydrologischen Dreieck (Bild 2) gemeinsam dargestellt werden. Die Analyse von Praxisbeispielen und Beispielrechnungen zeigt, dass Abweichungen in den Aufteilungswerten $a, g$ und $v$ gegenüber dem unbebauten Referenzzustand von 5 bis 10 Prozentpunkten erreichbar sind, wenn die vielfältigen Möglichkeiten der Niederschlagswasserbewirtschaftung genutzt werden. Die Abweichungen sind unter ökologischen, technischen und wirtschaftlichen Aspekten zu bewerten. Größere Abweichungen, die aus unvermeidbaren Randbedingungen oder Zwängen herrühren, sind ausführlich fachlich zu begründen und ihre Berücksichtigung im Rahmen von Ersatz- und Ausgleichsregelungen zu prüfen. — printed p.23', verification_note='md-verified 2026-09-05 (§5.3.3 Vergleich der Wasserbilanz im bebauten und unbebauten Zustand, printed p.23) [VC]', verified_at=now() where id='5809bbbf-d5ba-4d7d-8092-c1def561ec97' and verification_status not in ('verified_against_standard','corrected');
