-- ---------- M104-33 Abweichungsanalyse ----------
-- deviation_within_target
update public.fields set verification_status='verified_against_standard', verification_quote='Die Bilanzergebnisse können im hydrologischen Dreieck (Bild 2) gemeinsam dargestellt werden. Die Analyse von Praxisbeispielen und Beispielrechnungen zeigt, dass Abweichungen in den Aufteilungswerten $a, g$ und $v$ gegenüber dem unbebauten Referenzzustand von 5 bis 10 Prozentpunkten erreichbar sind, wenn die vielfältigen Möglichkeiten der Niederschlagswasserbewirtschaftung genutzt werden. Die Abweichungen sind unter ökologischen, technischen und wirtschaftlichen Aspekten zu bewerten. Größere Abweichungen, die aus unvermeidbaren Randbedingungen oder Zwängen herrühren, sind ausführlich fachlich zu begründen und ihre Berücksichtigung im Rahmen von Ersatz- und Ausgleichsregelungen zu prüfen. — printed p.23', verification_note='md-verified 2026-09-05 (§5.3.3 Vergleich der Wasserbilanz im bebauten und unbebauten Zustand, printed p.23; "5 bis 10 Prozentpunkte" is printed as achievable (erreichbar), not as a limit) [VC]', verified_at=now() where id='281b5c48-f1e2-4c9a-a1b2-b37dfdef7154' and verification_status not in ('verified_against_standard','corrected');
