-- corrective_measures
update public.fields set verification_status='verified_against_standard', verification_quote='In Bilanzgebieten, in denen eine entwässerungstechnische Versickerung aufgrund von Vorgaben des Arbeitsblatts DWA-A 138 nicht möglich ist bzw. aufgrund besonderer wasserwirtschaftlicher Randbedingungen nicht zielführend erscheint (z. B. bestehende Grundwasserabsenkung), kann die Grundwasserneubildung im Vergleich zum Referenzzustand deutlich abweichen. Zur Kompensation erhöhter Direktabflüsse sollten vornehmlich Maßnahmen zur Erhöhung der Verdunstung gewählt werden. — printed p.23', verification_note='md-verified 2026-09-05 (§5.3.4 Hinweise zur Durchführung, printed p.23) [VC]', verified_at=now() where id='a4a7d7cd-83a9-4e61-a936-903492b9b629' and verification_status not in ('verified_against_standard','corrected');

