-- ---------- Equations ----------
-- Gl. (1)
update public.equations set verification_status='verified_against_standard', verification_quote='Die Wasserhaushaltsgleichung lautet | P_{\text {korr }}=R+E T_{\mathrm{a}} \tag{1} — printed p.19–20', verification_note='md-verified 2026-09-05 (§5.1 Wasserhaushaltsgleichung, printed p.19–20) [VC]', verified_at=now() where id='681fdcea-c1f6-472d-9efb-1300e5bf1d4a' and verification_status <> 'verified_against_standard';
-- Gl. (2)
update public.equations set verification_status='verified_against_standard', verification_quote='Es gelten definitionsgemäß folgende Zusammenhänge (BfG 2003a): | & R=R_{\mathrm{D}}+R_{\mathrm{B}}  \tag{2}\\ — printed p.19–20', verification_note='md-verified 2026-09-05 (§5.1, printed p.19–20) [VC]', verified_at=now() where id='4430a74a-150d-43ad-880c-27c168aa02b3' and verification_status <> 'verified_against_standard';
-- Gl. (3)
update public.equations set verification_status='verified_against_standard', verification_quote='Es gelten definitionsgemäß folgende Zusammenhänge (BfG 2003a): | & R_{\mathrm{D}}=R_{\mathrm{D}, \mathrm{o}}+R_{\mathrm{D}, \mathrm{z}}  \tag{3}\\ — printed p.19–20', verification_note='md-verified 2026-09-05 (§5.1, printed p.19–20) [VC]', verified_at=now() where id='e59eb085-4e3e-4071-99ce-46e1ca5262a8' and verification_status <> 'verified_against_standard';
-- Gl. (4)
update public.equations set verification_status='verified_against_standard', verification_quote='Es gelten definitionsgemäß folgende Zusammenhänge (BfG 2003a): | & R_{\mathrm{B}}=G W N \tag{4} — printed p.19–20', verification_note='md-verified 2026-09-05 (§5.1, printed p.19–20) [VC]', verified_at=now() where id='3de1904c-874a-4076-aa63-ec3fe2725862' and verification_status <> 'verified_against_standard';
-- Gl. (5)
update public.equations set verification_status='verified_against_standard', verification_quote='Unter der vereinfachten Annahme von Gl. (4) leitet sich für die Abflusskomponente ab: | R_{\mathrm{D}}=R-G W N \tag{5} — printed p.19–20', verification_note='md-verified 2026-09-05 (§5.1, printed p.19–20) [VC]', verified_at=now() where id='c8a7ab70-c4db-4b17-bf96-2ee0f1ca4858' and verification_status <> 'verified_against_standard';
-- Gl. (6)
update public.equations set verification_status='verified_against_standard', verification_quote='Für die vereinfachte Wasserbilanz eines Gebiets gilt damit folgende Bestimmungsgleichung: | P_{\text {korr }}=R_{\mathrm{D}}+G W N+E T_{\mathrm{a}} \tag{6} — printed p.19–20', verification_note='md-verified 2026-09-05 (§5.1, printed p.19–20) [VC]', verified_at=now() where id='5cc33383-81ef-4d43-a5e8-02e6111bd7ac' and verification_status <> 'verified_against_standard';
-- Gl. (7)
update public.equations set verification_status='verified_against_standard', verification_quote='Die drei Komponenten Direktabfluss, Grundwasserneubildung und Verdunstung können als Anteile des Niederschlags durch dimensionslose Aufteilungswerte wie folgt beschrieben werden: | | $a=R_{\mathrm{D}} / P_{\text {korr }}$ | Aufteilungswert für den Direktabfluss $R_{\mathrm{D}}$ | — printed p.19–20', verification_note='md-verified 2026-09-05 (§5.1 Aufteilungswert a, printed p.19–20) [VC]', verified_at=now() where id='56a8fe84-7be5-4502-af62-ee36c3755e1b' and verification_status <> 'verified_against_standard';
-- Gl. (8)
update public.equations set verification_status='verified_against_standard', verification_quote='Die drei Komponenten Direktabfluss, Grundwasserneubildung und Verdunstung können als Anteile des Niederschlags durch dimensionslose Aufteilungswerte wie folgt beschrieben werden: | | $g=G W N / P_{\text {korr }}$ | Aufteilungswert für die Grundwasserneubildung GWN | — printed p.19–20', verification_note='md-verified 2026-09-05 (§5.1 Aufteilungswert g, printed p.19–20) [VC]', verified_at=now() where id='f4786b67-7b36-4a6e-9050-f6e1e57de5d7' and verification_status <> 'verified_against_standard';
-- Gl. (9)
update public.equations set verification_status='verified_against_standard', verification_quote='Die drei Komponenten Direktabfluss, Grundwasserneubildung und Verdunstung können als Anteile des Niederschlags durch dimensionslose Aufteilungswerte wie folgt beschrieben werden: | | $V=E T_{\mathrm{a}} / P_{\text {korr }}$ | Aufteilungswert für die Verdunstung $E T_{\mathrm{a}}$ | — printed p.19–20', verification_note='md-verified 2026-09-05 (§5.1 Aufteilungswert v, printed p.19–20) [VC]', verified_at=now() where id='d94e7f88-8bc3-4c2d-9df6-1c64372bee7b' and verification_status <> 'verified_against_standard';
-- Gl. (10)
update public.equations set verification_status='verified_against_standard', verification_quote='Für die Wasserbilanz befestigter und nicht befestigter Flächen gilt: | P_{\text {korr }}=R_{\mathrm{D}}+G W N+E T_{\mathrm{a}} & \text { in } \mathrm{mm} / \mathrm{a} \\ P_{\text {korr }}=a_{\mathrm{F}} \cdot P_{\text {korr }}+g_{\mathrm{F}} \cdot P_{\text {korr }}+v_{\mathrm{F}} \cdot P_{\text {korr }} & \text { in } \mathrm{mm} / \mathrm{a} \tag{10} — printed p.22', verification_note='md-verified 2026-09-05 (§5.3.2.2, printed p.22) [VC]', verified_at=now() where id='84363b16-16cc-45b5-a983-6d9b2c2dfc65' and verification_status <> 'verified_against_standard';
-- Gl. (11)
update public.equations set verification_status='verified_against_standard', verification_quote='Der Zufluss zu einer Bewirtschaftungsanlage ist der Direktabfluss der angeschlossenen befestigten Fläche. Bei großen, nach oben offenen Anlagen wird deren Überregnung zusätzlich mit in Ansatz gebracht. Der Zufluss wird aufgeteilt in die Komponenten Oberflächenabfluss, Grundwasserneubildung und Verdunstung. Es gilt: | Zufluss | Z=a_{\mathrm{F}} \cdot P_{\text {korr }} & \text { in } \mathrm{mm} / \mathrm{a} \\ — printed p.22', verification_note='md-verified 2026-09-05 (§5.3.2.3, printed p.22) [VC]', verified_at=now() where id='6da086d8-b051-465f-bf45-7763f8b2fa01' and verification_status <> 'verified_against_standard';
-- Gl. (12)
update public.equations set verification_status='verified_against_standard', verification_quote='Der Zufluss zu einer Bewirtschaftungsanlage ist der Direktabfluss der angeschlossenen befestigten Fläche. Bei großen, nach oben offenen Anlagen wird deren Überregnung zusätzlich mit in Ansatz gebracht. Der Zufluss wird aufgeteilt in die Komponenten Oberflächenabfluss, Grundwasserneubildung und Verdunstung. Es gilt: | Z=a_{\mathrm{A}} \cdot Z+g_{\mathrm{A}} \cdot Z+v_{\mathrm{A}} \cdot Z & \text { in } \mathrm{mm} / \mathrm{a} \tag{12} — printed p.22', verification_note='md-verified 2026-09-05 (§5.3.2.3, printed p.22) [VC]', verified_at=now() where id='2ab13f2f-5182-47dc-a0b7-1fec3330dbe9' and verification_status <> 'verified_against_standard';
