update public.equations set verification_status='verified_against_standard', verification_quote='Besondere Randbedingungen können im Siedlungsbereich die Verdunstung erhöhen oder vermindern. Hierzu gehören die Strahlungsexposition, die Solitärlage von Vegetation in bebauter Umgebung und die künstliche Bewässerung. Dies kann mit dem Lagefaktor $f_{\mathrm{L}}$ und dem Bewässerungsfaktor $f_{\mathrm{W}}$ aus Tabelle C. 6 berücksichtigt werden, sodass für die tatsächliche Verdunstung der Flächen gilt: | E T_{\mathrm{a}, \text { korr }}=E T_{\mathrm{a}} \cdot f_{\mathrm{L}} \cdot f_{\mathrm{W}} \tag{C.1} — printed p.43', verification_note='md-verified 2026-09-05 (§C.4.2 Gl. (C.1), printed p.43) [VC]', verified_at=now() where id='46d1fd5d-b497-4f0c-ba7b-43d10d3dd204' and verification_status <> 'verified_against_standard';
